async function downloadExport(kind,button){if(!gl&&!kind.startsWith('art-'))return;button.disabled=true;$('#status').textContent='Preparing '+kind.replaceAll('-',' ')+'…';try{const c=exportCanvas(kind);const blob=await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('PNG encoding failed')),'image/png'));const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='scalio-off-script-'+garment+'-'+color+'-'+kind+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('#status').textContent=kind.replaceAll('-',' ')+' PNG ready · '+c.width+' × '+c.height;}catch(e){$('#status').textContent='Export failed. Please try again.';console.error(e)}finally{button.disabled=false;}}
$('#download').onclick=e=>downloadExport('current',e.currentTarget);
